head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gParamObj;
scwin.gMarket = js_market; //시장구분

scwin.mode;
scwin.vScrenID = 'ULDSTF30009.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    if (frame.opener.key_dsicls_schdl_adm_dd == '') {
        scwin.mode = 'I';
        $c.stf.showObj(btn_Delete, false);
        scwin.fn_SetCode();
        $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
    } else {
        scwin.mode = 'U';
        scwin.fn_Read();
    }
};
scwin.fn_SetCode = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELIST_REAL_INVSTG_IN";
    dts_Save.Reset();
    dts_Save.insertRow();
};
scwin.fn_Read = function() {
    var url = "/DisclosureSchedule.do?method=readDelistRealInvstg";
    url += "&DSICLS_SCHDL_ADM_DD=" + frame.opener.key_dsicls_schdl_adm_dd;
    url += "&BYDD_SEQ=" + frame.opener.key_bydd_seq;
    url += "&INTEG_USR_ID=" + frame.opener.key_integ_usr_id;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Save.DataID = encodeURI(url);
    dts_Save.Reset();
    $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드]을 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ADM_DEADLINE_DD) == "") {
        $c.win.alert("[관리기한]을 선택하세요.");
        edt_ADM_DEADLINE_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SCHDL_ADM_ITM_TP_CD) == "") {
        $c.win.alert("[구분]을 선택하세요.");
        cmb_SCHDL_ADM_ITM_TP_CD.focus();
        return false;
    }
    if ($c.stf.checkMaxLength(txa_REMK, 2000, "비고")) {
        return true;
    }
};
scwin.fn_Save = function() {
    if (scwin.fn_CheckForm()) {
        var res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            var vCMD = (scwin.mode == "I") ? "insertDelistRealInvstg" : "modifyDelistRealInvstg";
            trs_Save.Action = "/DisclosureSchedule.do?method=" + vCMD + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.fn_Delete = function() {
    var res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        $c.stf.setObjectValue(cmb_SCHDL_ADM_ITM_TP_CD, '1'); //별의미없다 ts_save 는 데이터셋 값을 변경해줘야 인식하기 때문에 임의로 값을 바꾼다.

        trs_Save.Action = "/DisclosureSchedule.do?method=deleteDelistRealInvstg&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
        trs_Save.Post();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("저장 성공하였습니다.");
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.dts_Save_OnLoadCompleted = function(rowcount) {
    //alert(dts_Schedule.Text);

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    if (txb_ISUR_CD.readOnly == false) {
        Grd_com_isur.style.display = "none";
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Deadline_onclick = function() {
    popUpCalendar2(edt_ADM_DEADLINE_DD);
};
scwin.gform_onload = function() {
    $c.stf.showObj(Grd_com_isur, false);
    $c.stf.showObj(txb_EMP_NO, false);
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_Init();
};
